class Solution:
    def longestSubarray(self, nums: list[int], k: int) -> int:
        mx = max(nums)
        spf = list(range(mx + 1))
        i = 2
        while i * i <= mx:
            if spf[i] == i:
                for j in range(i * i, mx + 1, i):
                    if spf[j] == j:
                        spf[j] = i
            i += 1
        def primes(v):
            out = []
            while v > 1:
                p = spf[v]
                out.append(p)
                while v % p == 0:
                    v //= p
            return out
        cnt = {}
        left = ans = 0
        for r, x in enumerate(nums):
            for p in primes(x):
                cnt[p] = cnt.get(p, 0) + 1
            while len(cnt) > k:
                for p in primes(nums[left]):
                    cnt[p] -= 1
                    if cnt[p] == 0:
                        del cnt[p]
                left += 1
            ans = max(ans, r - left + 1)
        return ans

