class Solution {
public:
    int longestSubarray(vector<int>& nums, int k) {
        int mx = *max_element(nums.begin(), nums.end());
        vector<int> spf(mx + 1);
        iota(spf.begin(), spf.end(), 0);
        for (long long i = 2; i * i <= mx; i++)
            if (spf[i] == i)
                for (long long j = i * i; j <= mx; j += i)
                    if (spf[j] == j) spf[j] = i;
        auto primes = [&](int v, vector<int>& out) {
            while (v > 1) {
                int p = spf[v]; out.push_back(p);
                while (v % p == 0) v /= p;
            }
        };
        unordered_map<int, int> cnt;
        int left = 0, ans = 0;
        vector<int> ps;
        for (int r = 0; r < (int)nums.size(); r++) {
            ps.clear(); primes(nums[r], ps);
            for (int p : ps) cnt[p]++;
            while ((int)cnt.size() > k) {
                ps.clear(); primes(nums[left], ps);
                for (int p : ps) if (--cnt[p] == 0) cnt.erase(p);
                left++;
            }
            ans = max(ans, r - left + 1);
        }
        return ans;
    }
};

