class Solution {
    public int longestSubarray(int[] nums, int k) {
        int mx = 0;
        for (int x : nums) mx = Math.max(mx, x);
        int[] spf = new int[mx + 1];
        for (int i = 0; i <= mx; i++) spf[i] = i;
        for (long i = 2; i * i <= mx; i++)
            if (spf[(int)i] == i)
                for (long j = i * i; j <= mx; j += i)
                    if (spf[(int)j] == j) spf[(int)j] = (int)i;
        Map<Integer, Integer> cnt = new HashMap<>();
        int left = 0, ans = 0;
        List<Integer> ps = new ArrayList<>();
        for (int r = 0; r < nums.length; r++) {
            factor(nums[r], spf, ps);
            for (int p : ps) cnt.merge(p, 1, Integer::sum);
            while (cnt.size() > k) {
                factor(nums[left], spf, ps);
                for (int p : ps) cnt.computeIfPresent(p, (key, v) -> v == 1 ? null : v - 1);
                left++;
            }
            ans = Math.max(ans, r - left + 1);
        }
        return ans;
    }
    private void factor(int v, int[] spf, List<Integer> out) {
        out.clear();
        while (v > 1) {
            int p = spf[v]; out.add(p);
            while (v % p == 0) v /= p;
        }
    }
}

