var longestSubarray = function(nums, k) {
    const mx = Math.max(...nums);
    const spf = Array.from({length: mx + 1}, (_, i) => i);
    for (let i = 2; i * i <= mx; i++)
        if (spf[i] === i)
            for (let j = i * i; j <= mx; j += i)
                if (spf[j] === j) spf[j] = i;
    const factor = (v, out) => {
        out.length = 0;
        while (v > 1) {
            const p = spf[v]; out.push(p);
            while (v % p === 0) v /= p;
        }
    };
    const cnt = new Map();
    let left = 0, ans = 0;
    const ps = [];
    for (let r = 0; r < nums.length; r++) {
        factor(nums[r], ps);
        for (const p of ps) cnt.set(p, (cnt.get(p) || 0) + 1);
        while (cnt.size > k) {
            factor(nums[left], ps);
            for (const p of ps) {
                const c = cnt.get(p) - 1;
                c === 0 ? cnt.delete(p) : cnt.set(p, c);
            }
            left++;
        }
        ans = Math.max(ans, r - left + 1);
    }
    return ans;
};
